import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LeadershipDemo {

    private static final Logger log = Logger.getLogger(LeadershipDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Leading the instant-transfer initiative at " + BANK_NAME);

        ProjectPlanner planner = new ProjectPlanner();
        planner.add(new Milestone("validation", "Rajesh-team", "DONE", null));
        planner.add(new Milestone("real-time-ledger", "ledger-team", "DONE", "validation"));
        planner.add(new Milestone("fraud-checks", "risk-team", "IN_PROGRESS", "validation"));
        planner.add(new Milestone("notification", "comms-team", "IN_PROGRESS", "real-time-ledger"));

        log.info("Initial status check:");
        planner.reportBlocked();
        log.warning(() -> "Project ready? " + planner.isReady());

        // As the leader, I unblock fraud-checks and get notification completed.
        planner.updateStatus("fraud-checks", "DONE");
        planner.updateStatus("notification", "DONE");

        log.info("After unblocking and completing remaining milestones:");
        planner.reportBlocked();
        log.info(() -> "Project ready? " + planner.isReady());
    }
}

