class Milestone {
    private final String name;
    private final String owner;
    private String status;        // DONE or IN_PROGRESS
    private final String dependsOn; // name of prerequisite milestone, or null

    Milestone(String name, String owner, String status, String dependsOn) {
        this.name = name;
        this.owner = owner;
        this.status = status;
        this.dependsOn = dependsOn;
    }

    String getName() { return name; }
    String getOwner() { return owner; }
    String getStatus() { return status; }
    void setStatus(String status) { this.status = status; }
    String getDependsOn() { return dependsOn; }
    boolean isDone() { return "DONE".equals(status); }
}

// ─── Would be in planner/ProjectPlanner.java in a real project ───
class ProjectPlanner {
    private static final Logger log = Logger.getLogger(ProjectPlanner.class.getName());
    private final List<Milestone> milestones = new ArrayList<>();

    void add(Milestone m) {
        milestones.add(m);
        log.fine(() -> "Added milestone " + m.getName() + " owned by " + m.getOwner());
    }

    void updateStatus(String name, String status) {
        for (Milestone m : milestones) {
            if (m.getName().equals(name)) {
                m.setStatus(status);
                log.info(() -> "Milestone " + name + " -> " + status);
            }
        }
    }

    private Milestone find(String name) {
        for (Milestone m : milestones) {
            if (m.getName().equals(name)) {
                return m;
            }
        }
        return null;
    }

    // A milestone is blocked if it is not done AND its dependency is not done.
    void reportBlocked() {
        for (Milestone m : milestones) {
            if (!m.isDone() && m.getDependsOn() != null) {
                Milestone dep = find(m.getDependsOn());
                if (dep != null && !dep.isDone()) {
                    log.warning(() -> "BLOCKED: " + m.getName() + " waits on "
                            + dep.getName() + " (owner " + dep.getOwner() + ")");
                }
            }
            if (!m.isDone()) {
                log.info(() -> "In progress: " + m.getName() + " (owner " + m.getOwner() + ")");
            }
        }
    }

    boolean isReady() {
        for (Milestone m : milestones) {
            if (!m.isDone()) {
                return false;
            }
        }
        return true;
    }
}

